entRisk": {"additionalProperties": false, "properties": {"exposure_before": {"items": {"type": "string"}, "minItems": 1, "title": "Exposure Before", "type": "array"}, "exposure_after": {"items": {"type": "string"}, "minItems": 1, "title": "Exposure After", "type": "array"}, "protection_status": {"enum": ["adequate", "inadequate", "unknown", "not_applicable"], "title": "Protection Status", "type": "string"}, "costs_considered": {"items": {"type": "string"}, "minItems": 1, "title": "Costs Considered", "type": "array"}, "uncertainty": {"enum": ["high", "medium", "low"], "title": "Uncertainty", "type": "string"}}, "required": ["exposure_before", "exposure_after", "protection_status", "costs_considered", "uncertainty"], "title": "ManagementRisk", "type": "object"}, "MarketAnalysisRequestV1": {"additionalProperties": false, "properties": {"schema": {"const": "brooks.market-analysis-request.v1", "title": "Schema", "type": "string"}, "request_id": {"title": "Request Id", "type": "string"}, "symbol": {"title": "Symbol", "type": "string"}, "decision_time_ms": {"minimum": 0, "title": "Decision Time Ms", "type": "integer"}, "timeframes": {"items": {"type": "string"}, "minItems": 1, "title": "Timeframes", "type": "array"}, "market_fields": {"items": {"enum": ["ordered_ohlc", "bar_by_bar", "decision_time"], "type": "string"}, "minItems": 1, "title": "Market Fields", "type": "array"}}, "required": ["schema", "request_id", "symbol", "decision_time_ms", "timeframes", "market_fields"], "title": "MarketAnalysisRequestV1", "type": "object"}}, "additionalProperties": false, "properties": {"schema": {"const": "brooks.management-decision.v2", "title": "Schema", "type": "string"}, "role": {"const": "POSITION_MANAGER", "title": "Role", "type": "string"}, "decision_time_ms": {"minimum": 0, "title": "Decision Time Ms", "type": "integer"}, "action": {"enum": ["HOLD", "REDUCE", "CLOSE", "HEDGE", "INCREASE_HEDGE", "REDUCE_HEDGE", "REMOVE_HEDGE", "REQUEST_MARKET_ANALYSIS", "RECONCILE_STATE", "MAN